class Solution {
    public int preimageSizeFZF(int k) {
        return (int) (firstAtLeast(k + 1L) - firstAtLeast(k));
    }

    private long firstAtLeast(long target) {
        long left = 0;
        long right = 5L * (target + 1);
        while (left < right) {
            long mid = left + (right - left) / 2;
            if (trailingZeroes(mid) >= target) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }

    private long trailingZeroes(long n) {
        long total = 0;
        while (n > 0) {
            n /= 5;
            total += n;
        }
        return total;
    }
}

class Solution {
    public int preimageSizeFZF(int k) {
        long left = 0;
        long right = 5L * (k + 1);
        while (left < right) {
            long mid = (left + right) >>> 1;
            if (countZeroes(mid) >= k) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return countZeroes(left) == k ? 5 : 0;
    }

    private long countZeroes(long n) {
        if (n == 0) {
            return 0;
        }
        return n / 5 + countZeroes(n / 5);
    }
}

class Solution {
    public int preimageSizeFZF(int k) {
        long left = 0;
        long right = 5L * (k + 1);
        while (left <= right) {
            long mid = (left + right) >>> 1;
            long zeroes = trailingZeroes(mid);
            if (zeroes == k) {
                return 5;
            }
            if (zeroes < k) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return 0;
    }

    private long trailingZeroes(long n) {
        long total = 0;
        for (long divisor = 5; divisor <= n; divisor *= 5) {
            total += n / divisor;
        }
        return total;
    }
}

